package com.project.util;

import java.sql.Connection;
import java.sql.Statement;
import java.sql.SQLException;

public class SchemaUpdate {
    public static void main(String[] args) {
        String[] sqls = {
            "CREATE TABLE posts (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id NUMBER NOT NULL, title VARCHAR2(255) NOT NULL, content VARCHAR2(4000) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_post_user FOREIGN KEY (user_id) REFERENCES users(id))",
            "CREATE TABLE comments (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, post_id NUMBER NOT NULL, user_id NUMBER NOT NULL, parent_comment_id NUMBER, content VARCHAR2(4000) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_comment_post FOREIGN KEY (post_id) REFERENCES posts(id), CONSTRAINT fk_comment_user FOREIGN KEY (user_id) REFERENCES users(id), CONSTRAINT fk_comment_parent FOREIGN KEY (parent_comment_id) REFERENCES comments(id) ON DELETE CASCADE)"
        };

        try (Connection conn = DBUtil.getConnection();
             Statement stmt = conn.createStatement()) {
            
            for (String sql : sqls) {
                try {
                    stmt.execute(sql);
                    System.out.println("Executed: " + sql);
                } catch (SQLException e) {
                    if (e.getMessage().contains("name is already used")) {
                        System.out.println("Table already exists, skipping: " + sql);
                    } else {
                        System.err.println("Error executing: " + sql);
                        e.printStackTrace();
                    }
                }
            }
            System.out.println("Schema update completed.");
            
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}
